<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Personal Expense Tracker</title>
<style>
  :root {
    --bg: #f6f7f9;
    --card: #ffffff;
    --text: #1f2430;
    --muted: #6b7280;
    --border: #d9dde3;
    --accent: #2f6fed;
    --danger: #c0392b;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.4;
  }
  main {
    max-width: 720px;
    margin: 0 auto;
    padding: 24px 16px 48px;
  }
  h1 { font-size: 1.4rem; margin: 0 0 16px; }
  h2 { font-size: 1rem; margin: 0 0 10px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
  section {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 16px;
  }
  form .fields {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: flex-end;
  }
  .field { display: flex; flex-direction: column; gap: 4px; }
  label { font-size: .82rem; color: var(--muted); }
  input, select, button {
    font: inherit;
    padding: 7px 9px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: var(--text);
  }
  input:focus, select:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
  #amount { width: 110px; }
  #note { width: 180px; }
  #add-expense {
    background: var(--accent);
    color: #fff;
    border-color: var(--accent);
    cursor: pointer;
    padding: 8px 16px;
  }
  #add-expense:hover { filter: brightness(1.08); }
  #form-error {
    color: var(--danger);
    font-size: .9rem;
    min-height: 1.2em;
    margin-top: 8px;
  }
  .filters {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: flex-end;
  }
  #expense-list { margin-top: 4px; }
  .expense {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 4px;
    border-bottom: 1px solid var(--border);
  }
  .expense:last-child { border-bottom: none; }
  .exp-amount { font-weight: 600; min-width: 80px; text-align: right; font-variant-numeric: tabular-nums; }
  .exp-cat {
    background: #eef2fb;
    color: var(--accent);
    border-radius: 999px;
    padding: 2px 10px;
    font-size: .82rem;
    text-transform: capitalize;
  }
  .exp-date { color: var(--muted); font-size: .88rem; min-width: 90px; }
  .exp-note { color: var(--muted); font-size: .88rem; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .exp-del {
    background: #fff;
    color: var(--danger);
    border: 1px solid var(--border);
    border-radius: 6px;
    cursor: pointer;
    padding: 4px 10px;
    margin-left: auto;
  }
  .exp-del:hover { background: #fdecea; border-color: var(--danger); }
  .totals-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 10px;
  }
  #total { font-size: 1.3rem; font-weight: 700; font-variant-numeric: tabular-nums; }
  .cat-totals { display: flex; flex-wrap: wrap; gap: 8px; }
  .cat-total {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 6px 10px;
    font-size: .88rem;
    text-transform: capitalize;
    font-variant-numeric: tabular-nums;
  }
  .empty { color: var(--muted); font-style: italic; padding: 10px 4px; }
</style>
</head>
<body>
<main>
  <h1>Personal Expense Tracker</h1>

  <section>
    <h2>Add expense</h2>
    <form id="expense-form" novalidate>
      <div class="fields">
        <div class="field">
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" min="0" placeholder="0.00">
        </div>
        <div class="field">
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div class="field">
          <label for="date">Date</label>
          <input type="date" id="date">
        </div>
        <div class="field">
          <label for="note">Note (optional)</label>
          <input type="text" id="note" placeholder="e.g. weekly shop">
        </div>
        <button type="submit" id="add-expense">Add</button>
      </div>
      <div id="form-error" role="alert" aria-live="polite"></div>
    </form>
  </section>

  <section>
    <h2>Filters</h2>
    <div class="filters">
      <div class="field">
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div class="field">
        <label for="filter-from">From</label>
        <input type="date" id="filter-from">
      </div>
      <div class="field">
        <label for="filter-to">To</label>
        <input type="date" id="filter-to">
      </div>
      <button type="button" id="clear-filters">Clear filters</button>
    </div>
  </section>

  <section>
    <div class="totals-row">
      <h2 style="margin:0">Summary (visible)</h2>
      <div>Total: <span id="total">0.00</span></div>
    </div>
    <div class="cat-totals" id="cat-totals"></div>
  </section>

  <section>
    <h2>Expenses</h2>
    <div id="expense-list"></div>
  </section>
</main>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'expense-tracker-expenses';
  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

  var amountEl = document.getElementById('amount');
  var categoryEl = document.getElementById('category');
  var dateEl = document.getElementById('date');
  var noteEl = document.getElementById('note');
  var formEl = document.getElementById('expense-form');
  var errorEl = document.getElementById('form-error');
  var listEl = document.getElementById('expense-list');
  var totalEl = document.getElementById('total');
  var catTotalsEl = document.getElementById('cat-totals');
  var filterCatEl = document.getElementById('filter-category');
  var filterFromEl = document.getElementById('filter-from');
  var filterToEl = document.getElementById('filter-to');
  var clearFiltersEl = document.getElementById('clear-filters');

  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (e) {
        return e && typeof e.amount === 'number' && isFinite(e.amount) &&
               typeof e.category === 'string' && typeof e.date === 'string';
      });
    } catch (err) {
      return [];
    }
  }

  function saveExpenses() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) { /* storage unavailable; app keeps working in-memory */ }
  }

  var expenses = loadExpenses();
  var nextId = expenses.reduce(function (m, e) {
    return Math.max(m, typeof e.id === 'number' ? e.id : 0);
  }, 0) + 1;

  function isVisible(exp) {
    var cat = filterCatEl.value;
    if (cat !== 'all' && exp.category !== cat) return false;
    var from = filterFromEl.value;
    var to = filterToEl.value;
    if (from && exp.date < from) return false;
    if (to && exp.date > to) return false;
    return true;
  }

  function render() {
    listEl.innerHTML = '';
    var visible = [];

    // newest first: sort by date desc, then by insertion (id) desc for ties
    var sorted = expenses.slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return b.id - a.id;
    });

    sorted.forEach(function (exp) {
      if (!isVisible(exp)) return;
      visible.push(exp);

      var row = document.createElement('div');
      row.className = 'expense';
      row.dataset.id = exp.id;

      var amt = document.createElement('span');
      amt.className = 'exp-amount';
      amt.textContent = exp.amount.toFixed(2);

      var cat = document.createElement('span');
      cat.className = 'exp-cat';
      cat.textContent = exp.category;

      var date = document.createElement('span');
      date.className = 'exp-date';
      date.textContent = exp.date;

      var note = document.createElement('span');
      note.className = 'exp-note';
      note.textContent = exp.note || '';
      note.title = exp.note || '';

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'exp-del';
      del.textContent = 'Delete';
      del.setAttribute('aria-label', 'Delete expense of ' + exp.amount.toFixed(2) + ' on ' + exp.date);
      del.addEventListener('click', function () {
        expenses = expenses.filter(function (e) { return e.id !== exp.id; });
        saveExpenses();
        render();
      });

      row.appendChild(amt);
      row.appendChild(cat);
      row.appendChild(date);
      row.appendChild(note);
      row.appendChild(del);
      listEl.appendChild(row);
    });

    if (visible.length === 0) {
      var empty = document.createElement('div');
      empty.className = 'empty';
      empty.textContent = expenses.length === 0
        ? 'No expenses yet — add one above.'
        : 'No expenses match the current filters.';
      listEl.appendChild(empty);
    }

    var total = visible.reduce(function (s, e) { return s + e.amount; }, 0);
    totalEl.textContent = total.toFixed(2);

    catTotalsEl.innerHTML = '';
    CATEGORIES.forEach(function (c) {
      var catTotal = visible.reduce(function (s, e) {
        return e.category === c ? s + e.amount : s;
      }, 0);
      var el = document.createElement('span');
      el.className = 'cat-total';
      el.setAttribute('data-cat', c);
      el.textContent = c + ': ' + catTotal.toFixed(2);
      catTotalsEl.appendChild(el);
    });
  }

  formEl.addEventListener('submit', function (ev) {
    ev.preventDefault();

    var rawAmount = amountEl.value.trim();
    var amount = parseFloat(rawAmount);
    var date = dateEl.value;

    if (rawAmount === '' || isNaN(amount) || !isFinite(amount)) {
      errorEl.textContent = 'Please enter a valid numeric amount.';
      return;
    }
    if (amount <= 0) {
      errorEl.textContent = 'Amount must be greater than zero.';
      return;
    }
    if (!date) {
      errorEl.textContent = 'Please choose a date for the expense.';
      return;
    }

    expenses.push({
      id: nextId++,
      amount: Math.round(amount * 100) / 100,
      category: categoryEl.value,
      date: date,
      note: noteEl.value.trim()
    });
    saveExpenses();

    errorEl.textContent = '';
    amountEl.value = '';
    noteEl.value = '';
    amountEl.focus();
    render();
  });

  filterCatEl.addEventListener('change', render);
  filterFromEl.addEventListener('change', render);
  filterFromEl.addEventListener('input', render);
  filterToEl.addEventListener('change', render);
  filterToEl.addEventListener('input', render);

  clearFiltersEl.addEventListener('click', function () {
    filterCatEl.value = 'all';
    filterFromEl.value = '';
    filterToEl.value = '';
    render();
  });

  render();
})();
</script>
</body>
</html>
